SELECT A.IND_ID indId, A.IND_NAME indName, A.IND_TYPE indType, A.SUP_TYPE supType, A.WARN_COND warnCond, A.FOUL_COND foulCond, A.APPROVE_COND approveCond, A.IS_ENABLED isEnabled, A.IS_ADJUST isAdjust, A.ADJUST adjust, A.IND_NUM indNum, A.SUP_DOC supDoc FROM RSK_ISUP_INDICATOR A
A.IND_NAME LIKE CONCAT(CONCAT('%',#{indName}),'%')
AND A.IND_TYPE = #{indType,jdbcType=VARCHAR}
AND A.SUP_TYPE = #{supType,jdbcType=VARCHAR}


select distinct t.PORTFOLIO_ID id,m.PORTFOLIO_NAME name,m.PROFIT_TYPE pId,m.RISK_ENABLED object
 from PA_PTL_PORTFOLIO t
 inner join  PTL_PORTFOLIO m on t.PORTFOLIO_ID=m.PORTFOLIO_ID
 left join prd_sale_param n on 'F16_'||m.PORTFOLIO_ID=n.FINPROD_ID



		t.PORTFOLIO_ID not in (select PORTFOLIO_ID from RSK_PORTFOLIO_INDICATOR where PORTFOLIO_LEVEL =#{portfLevel} and IND_ID =#{indId} )


		and (m.PORTFOLIO_NAME LIKE CONCAT(CONCAT('%',#{portfName}),'%')
		or m.PORTFOLIO_ID like CONCAT(CONCAT('%',#{portfName}),'%'))


		and m.PROFIT_TYPE = #{profitType}


		and t.OPEN_TYPE = #{issueMode}


		and t.RAISE_TYPE = #{raiseType}


		and t.INVEST_NATURE = #{investType}


		and n.IS_FACE_SINGLEINVESTOR = #{isFaceSingleInvestor}

	and m.PORTFOLIO_TYPE in ('01','02') and  m.MDATE  >=  to_date(#{platDate},'yyyy-MM-dd')

 	select distinct t.PORTFOLIO_ID id,m.PORTFOLIO_NAME name,${fields} as pId,m.RISK_ENABLED object
